package ru.neverland.mintcontracts.service;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.function.Supplier;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
import ru.neverland.mintcontracts.integration.TownyHook;
import ru.neverland.mintcontracts.api.BuildingProcurementApi;

/** Legacy command/menu now delegates every purchase to the same guarded public API used by CraftoUI. */
public final class BuildOrders implements CommandExecutor,Listener {
    private final JavaPlugin plugin;private final BuildingProcurementApi procurement;
    public BuildOrders(JavaPlugin plugin,TownyHook towns,BuildingProcurementApi procurement){this.plugin=plugin;this.procurement=procurement;plugin.getServer().getPluginManager().registerEvents(this,plugin);towns.register("buildorders",this);plugin.getCommand("townybuildorders").setExecutor(this);}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p))return true;SuiteScheduler.player(plugin,p,ignored->{try{if(procurement==null)throw new IllegalArgumentException("Закупки приостановлены; прежние городские контракты продолжают работать");if(args.length==0||args.length==1&&args[0].equalsIgnoreCase("mine"))requests(p,1);else if(args.length==2&&args[0].equalsIgnoreCase("status"))order(p,UUID.fromString(args[1]));else if(args.length==1)offers(p,args[0]);else throw new IllegalArgumentException("/t buildorders <здание> или /t buildorders mine");}catch(Exception error){p.sendMessage("§e"+reason(error));}});return true;}
    public static long money(String value){try{long cents=new BigDecimal(value).movePointRight(2).longValueExact();if(cents<=0||cents>100_000_000_000L)throw new IllegalArgumentException();return cents;}catch(Exception error){throw new IllegalArgumentException("Неверная ставка или предел награды в настройках заказов на стройку");}}
    private static final class View implements InventoryHolder{final UUID owner;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID owner){this.owner=owner;}public Inventory getInventory(){return inventory;}}
    private View view(Player player,String title){var v=new View(player.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,54,title);button(v,22,Material.CLOCK,"Проверяем условия",List.of("Сохранённые деньги и ресурсы не изменяются"),null);button(v,49,Material.BARRIER,"Закрыть",List.of(),player::closeInventory);player.openInventory(v.inventory);return v;}
    private boolean current(Player p,View v){return p.isOnline()&&p.getUniqueId().equals(v.owner)&&p.getOpenInventory().getTopInventory()==v.inventory;}
    private void button(View v,int slot,Material material,String title,List<String> lore,Runnable action){var item=new ItemStack(material);var meta=item.getItemMeta();meta.displayName(MenuStyle.nameComponent(MenuStyle.decode("§b"+title)));meta.lore(MenuStyle.loreComponents(lore.stream().map(s->MenuStyle.decode("§7"+s)).toList()));meta.addItemFlags(ItemFlag.values());item.setItemMeta(meta);v.inventory.setItem(slot,item);if(action==null)v.actions.remove(slot);else v.actions.put(slot,action);}
    private <T>void load(Player p,View v,CompletionStage<T> stage,Consumer<T> render){stage.whenComplete((value,error)->{if(!plugin.isEnabled())return;SuiteScheduler.player(plugin,p,ignored->{if(!current(p,v))return;v.inventory.clear();v.actions.clear();button(v,49,Material.BARRIER,"Закрыть",List.of(),p::closeInventory);if(error!=null){button(v,22,Material.BARRIER,"Операция пока недоступна",List.of(reason(error),"Оплаченный резерв сохраняется.","Откройте мои закупки для сверки."),null);button(v,45,Material.WRITABLE_BOOK,"Мои закупки",List.of(),()->requests(p,1));return;}try{render.accept(value);}catch(Exception failure){button(v,22,Material.BARRIER,"Нужна проверка",List.of(reason(failure)),null);}});});}
    private void offers(Player player,String project){var v=view(player,"Материалы для здания");load(player,v,procurement.offers(player,project),rows->{int slot=0;for(var row:rows){String key=(String)row.get("itemKey");button(v,slot++,Material.CHEST,(String)row.get("name"),List.of("Здание: "+row.get("building")+" • ур. "+row.get("targetLevel"),"Нужно принести: "+row.get("amount"),"Награда из казны: "+amount(row.get("rewardCents")),"Уже заказанные поставки учтены.","Нажмите: точная смета и подтверждение"),()->quote(player,project,key));}if(rows.isEmpty())button(v,22,Material.LIME_DYE,"Материалы уже обеспечены",List.of("Учтены фонд здания, склад и открытые закупки."),null);button(v,45,Material.ARROW,"К зданию",List.of(),()->player.performCommand("town builds "+project));button(v,53,Material.WRITABLE_BOOK,"Мои закупки",List.of(),()->requests(player,1));});}
    private void quote(Player player,String project,String itemKey){var v=view(player,"Подтвердить городской заказ");load(player,v,procurement.quote(player,project,itemKey),row->draw(player,v,row,true));}
    private void order(Player player,UUID id){var v=view(player,"Состояние городской закупки");load(player,v,procurement.status(player,id),row->draw(player,v,row,false));}
    private static String state(String value){return switch(value){case "QUOTE"->"Ожидает вашего подтверждения";case "FUNDING"->"Казна подтверждает оплату";case "FUNDED"->"Оплачено; осталось опубликовать заказ";case "PUBLISHING"->"Публикация ожидает сверки";case "PUBLISHED"->"Опубликован в городских контрактах";case "SETTLED"->"Городской контракт закрыт";case "REJECTED"->"Списание отклонено";case "REVIEW"->"Оплата требует сверки администратора";case "CANCELLED"->"Отменено до оплаты";case "REFUNDING"->"Казна подтверждает возврат";case "REFUNDED"->"Резерв возвращён городу";default->"Состояние требует проверки";};}
    private void draw(Player player,View v,Map<String,Object> row,boolean initial){UUID id=UUID.fromString((String)row.get("requestId"));String status=(String)row.get("status");button(v,13,Material.BOOK,(String)row.get("name"),List.of("Здание: "+row.get("building")+" • ур. "+row.get("targetLevel"),"Количество: "+row.get("amount"),"Из казны: "+amount(row.get("rewardCents")),"Срок заказа: "+(((Number)row.get("durationSeconds")).longValue()/3600)+" ч.",state(status),String.valueOf(row.get("detail"))),null);button(v,31,Material.CHEST,"Куда поступят материалы",List.of("Поставка придёт на общий городской склад.","Условия после оплаты фиксируются.","Фонд здания при публикации не расходуется.","Награду обеспечивает казна, не сервер."),null);button(v,45,Material.WRITABLE_BOOK,"Мои закупки",List.of(),()->requests(player,1));button(v,47,Material.SPYGLASS,"Сверить состояние",List.of("Не повторяет подтверждённое списание"),()->order(player,id));
        if(Set.of("QUOTE","FUNDING","FUNDED","PUBLISHING").contains(status))button(v,20,Material.LIME_DYE,status.equals("QUOTE")?"Оплатить и опубликовать":"Продолжить сохранённую закупку",List.of("Повторно проверяются права текущего мэра.","Результат неизвестного списания не повторяется."),()->act(player,v,20,()->procurement.confirm(player,id),id));else button(v,20,Material.GRAY_DYE,"Публикация недоступна",List.of(state(status)),null);
        if(Set.of("QUOTE","FUNDED","PUBLISHING","REFUNDING").contains(status))button(v,24,Material.RED_DYE,"Отменить и вернуть резерв",List.of("Только до публикации и выплат игрокам.","Подтвердите отмену в следующем окне."),()->cancel(player,id,row));else button(v,24,Material.GRAY_DYE,"Отмена здесь недоступна",List.of(status.equals("PUBLISHED")?"Опубликованный заказ отменяется в /t contracts.":state(status)),null);
        if(status.equals("PUBLISHED"))button(v,53,Material.CHEST,"Открыть городские контракты",List.of(),()->player.performCommand("town contracts"));}
    private void cancel(Player player,UUID id,Map<String,Object> row){var v=view(player,"Подтвердить отмену закупки");v.inventory.clear();v.actions.clear();button(v,13,Material.BOOK,(String)row.get("name"),List.of("Заказ ещё не должен быть опубликован.","Резерв: "+amount(row.get("rewardCents")),"Возврат подтверждается казной один раз."),null);button(v,20,Material.RED_DYE,"Подтвердить отмену",List.of(),()->act(player,v,20,()->procurement.cancel(player,id),id));button(v,24,Material.ARROW,"Вернуться",List.of("Без изменений"),()->order(player,id));}
    private void act(Player p,View v,int slot,Supplier<CompletionStage<Map<String,Object>>> work,UUID id){if(v.actions.remove(slot)==null)return;button(v,slot,Material.CLOCK,"Сохраняем действие",List.of("Дождитесь ответа"),null);load(p,v,work.get(),row->draw(p,v,row,false));}
    private void requests(Player player,int page){var v=view(player,"Закупки города • "+page);load(player,v,procurement.requests(player,page),rows->{int slot=0;for(var row:rows){UUID id=UUID.fromString((String)row.get("requestId"));button(v,slot++,Material.PAPER,(String)row.get("name"),List.of("Количество: "+row.get("amount"),state((String)row.get("status")),"Резерв: "+amount(row.get("rewardCents")),"Нажмите: подробности и сверка"),()->order(player,id));}if(rows.isEmpty())button(v,22,Material.BOOK,"Закупок пока нет",List.of("Откройте здание и выберите заказ материалов."),null);if(page>1)button(v,45,Material.ARROW,"Предыдущая страница",List.of(),()->requests(player,page-1));if(rows.size()==20)button(v,53,Material.ARROW,"Следующая страница",List.of(),()->requests(player,page+1));});}
    @EventHandler public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof View v))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player p)||!current(p,v)||event.getClick()!=ClickType.LEFT)return;var action=v.actions.get(event.getRawSlot());if(action!=null)SuiteScheduler.player(plugin,p,ignored->{if(!current(p,v))return;try{action.run();}catch(Exception error){p.sendMessage("§e"+reason(error));}});}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof View)event.setCancelled(true);}
    private static String amount(Object cents){return BigDecimal.valueOf(((Number)cents).longValue(),2).toPlainString()+" монет";}
    private static String reason(Throwable error){while(error.getCause()!=null&&(error instanceof CompletionException||error instanceof java.lang.reflect.InvocationTargetException))error=error.getCause();return error.getMessage()==null?"Закупки временно недоступны":error.getMessage();}
    public void close(){SuiteScheduler.cleanupPlayers(plugin,p->{if(p.getOpenInventory().getTopInventory().getHolder() instanceof View)p.closeInventory();});}
}
